contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint _val) public payable {
        // ensure we are in the initialization phase
        require(c.MinSum() == 0, "precondition: MinSum must be zero before initialization");

        // enter the initialized phase
        c.Initialized(); if (__ESBMC_reverted()) return;

        // read MinSum before the failing call
        uint before = c.MinSum(); if (__ESBMC_reverted()) return;

        // attempt to change MinSum after initialization; this must revert
        bool reverted;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // general rule: the call reverts and the stored MinSum is unchanged
        assert(reverted && c.MinSum() == before);
    }
}

